import * as THREE from 'three';import{GLTFLoader}from'three/addons/loaders/GLTFLoader.js';import{DRACOLoader}from'three/addons/loaders/DRACOLoader.js';import{OrbitControls}from'three/addons/controls/OrbitControls.js';
const $=id=>document.getElementById(id),view=$('view'),scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(35,1,.03,80),renderer=new THREE.WebGLRenderer({canvas:$('canvas'),antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.1;scene.background=new THREE.Color('#0b0d11');scene.add(new THREE.HemisphereLight('#dce6f5','#11131b',1.8));let key=new THREE.DirectionalLight('#fff0cf',4);key.position.set(-4,7,5);scene.add(key);let rim=new THREE.DirectionalLight('#6e9fff',3);rim.position.set(4,4,-4);scene.add(rim);let ground=new THREE.Mesh(new THREE.CircleGeometry(2.4,96),new THREE.MeshStandardMaterial({color:'#171a20',metalness:.75,roughness:.3}));ground.rotation.x=-Math.PI/2;ground.position.y=-.045;scene.add(ground);const orbit=new OrbitControls(camera,renderer.domElement);orbit.enableDamping=true;orbit.target.set(0,1.6,0);camera.position.set(4.6,2.8,7.8);let motion={},parts=[],t=0,target=0,playing=false,last=performance.now(),tmp=new THREE.Vector3(),quat=new THREE.Quaternion();function resize(){let w=view.clientWidth,h=view.clientHeight;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix()}new ResizeObserver(resize).observe(view);resize();function apply(){let x=t*96,lo=Math.floor(x),hi=Math.min(96,lo+1),f=x-lo;for(let o of parts){let a=motion[o.name][lo],b=motion[o.name][hi];o.position.fromArray(a.p).lerp(tmp.fromArray(b.p),f);o.quaternion.fromArray(a.q).slerp(quat.fromArray(b.q),f);o.scale.fromArray(a.s).lerp(tmp.fromArray(b.s),f);let alpha=THREE.MathUtils.lerp(a.a,b.a,f);o.visible=alpha>.01;o.material.opacity=alpha;o.material.transparent=alpha<.99;o.material.depthWrite=alpha>.99}$('progress').style.width=t*100+'%';$('percent').textContent=String(Math.round(t*100)).padStart(2,'0')+'%';$('state').textContent=t>.98?'汽车':t<.02?'人形':'变形中';$('status').textContent=playing?'变形进行中':t>.98?'汽车状态':'人形状态'}function setTarget(x){target=x;playing=true}$('play').onclick=()=>setTarget(target>.5?0:1);$('forward').onclick=()=>setTarget(1);$('back').onclick=()=>setTarget(0);async function load(){try{let dr=new DRACOLoader().setDecoderPath('/vendor/draco/'),loader=new GLTFLoader().setDRACOLoader(dr),[d,g]=await Promise.all([fetch('/assets/exhibit-motion.json').then(r=>r.json()),loader.loadAsync('/assets/exhibit.glb')]);motion=d;g.scene.traverse(o=>{if(o.isMesh&&motion[o.name]){parts.push(o);o.material=o.material.clone();o.material.metalness=.7;o.material.roughness=.32;o.castShadow=true;o.receiveShadow=true}});scene.add(g.scene);apply();$('loading').classList.add('done');$('play').disabled=false;$('back').disabled=false;$('forward').disabled=false;dr.dispose()}catch(e){$('loading').textContent='模型载入失败，请刷新重试'}}function loop(now){requestAnimationFrame(loop);let dt=Math.min(.05,(now-last)/1000);last=now;if(playing){let d=Math.sign(target-t);t+=d*Math.min(Math.abs(target-t),dt/3);if(Math.abs(target-t)<.001){t=target;playing=false}}apply();orbit.update();renderer.render(scene,camera)}$('play').disabled=true;$('back').disabled=true;$('forward').disabled=true;load();requestAnimationFrame(loop);
